command:
curl -sS -m 60 'https://openrouter.ai/api/v1/models?sort=top-weekly' -o /tmp/models.json; ls -la /tmp/models.json
node -e "
const d = JSON.parse(require('fs').readFileSync('/tmp/models.json','utf8')).data;
const html = require('fs').readFileSync('index.html','utf8');
const block = html.slice(html.indexOf('const COMPANY_LOGOS = {'), html.indexOf('function companyLogoSrc'));
const logos = new Set([...block.matchAll(/(?:'([^']+)'|([a-z0-9]+)):\s*'[a-z0-9]+'/gi)].map(m => m[1] || m[2]));
const isChat = (entry) => { const id = String((entry && entry.id) || ''); const arch = (entry && entry.architecture) || {}; const input = arch.input_modalities || ['text']; const output = arch.output_modalities || ['text']; return !!id && !id.startsWith('~') && !id.endsWith(':batch') && input.includes('text') && output.includes('text') && !output.includes('image') && !output.includes('audio'); };
const chat = d.filter(isChat);
console.log('total', d.length, 'chat', chat.length, 'logo slugs', logos.size);
const keys = new Map(); chat.forEach(e => { if (e.benchmarks) Object.keys(e.benchmarks).forEach(k => keys.set(k, (keys.get(k)||0)+1)); });
console.log('benchmark keys', JSON.stringify([...keys]));
const aa = chat.filter(e => e.benchmarks && e.benchmarks.artificial_analysis);
const iq = aa.filter(e => typeof e.benchmarks.artificial_analysis.intelligence_index === 'number');
console.log('with artificial_analysis', aa.length, 'with intelligence_index', iq.length);
const sample = chat.find(e => e.benchmarks);
console.log('sample benchmarks', sample && sample.id, JSON.stringify(sample && sample.benchmarks).slice(0, 400));
console.log('--- first 40 in top-weekly order: id | iq | logo?');
chat.slice(0, 40).forEach((e, i) => { const slug = e.id.split('/')[0]; const b = e.benchmarks && e.benchmarks.artificial_analysis; console.log(String(i).padStart(2), e.id.padEnd(46), b && typeof b.intelligence_index === 'number' ? b.intelligence_index : '—', logos.has(slug.replace(/^~/, '')) ? 'logo' : 'NO-LOGO(' + slug + ')'); });
const noLogo = new Map(); chat.forEach(e => { const s = e.id.split('/')[0]; if (!logos.has(s.replace(/^~/, ''))) noLogo.set(s, (noLogo.get(s) || 0) + 1); });
console.log('companies without a logo', JSON.stringify([...noLogo].sort((a, b) => b[1] - a[1])));
const noIq = chat.filter(e => !(e.benchmarks && e.benchmarks.artificial_analysis && typeof e.benchmarks.artificial_analysis.intelligence_index === 'number')).slice(0, 25).map(e => e.id);
console.log('first models with no intelligence index', JSON.stringify(noIq));
"
